create or replace function hnk_private.validate_day060_completion_v2(p_evidence jsonb,p_expected_source_sha text)
returns void language plpgsql set search_path='' as $$
declare o jsonb; b jsonb; p jsonb; c jsonb; m jsonb; legacy jsonb; k text; i integer; stopped boolean; r text;
begin
 if jsonb_typeof(p_evidence) is distinct from 'object' then raise exception 'day060_v2_evidence_object_required'; end if;
 if exists(select 1 from jsonb_object_keys(p_evidence) x where x not in ('protocol_version','source_sha','session_id','mode','public_duration_seconds','partner_duration_seconds','public_observations','public_boundaries','partner_control','comparison','middle','vault_entry_ref','vault_payload_no_identifying_data_confirmed','voluntary_completion_confirmed','final_safety_clear_confirmed','safety_stop_occurred','safety_stop_reason')) then raise exception 'day060_v2_unknown_top_field'; end if;
 if p_evidence->>'protocol_version' is distinct from 'HNK-CHOKMAH-D060-V2' then raise exception 'day060_v2_protocol_invalid'; end if;
 if p_evidence->>'source_sha' is distinct from p_expected_source_sha or p_expected_source_sha is distinct from 'e98e8925c8e03555c39b033813999d6a488149a9' then raise exception 'day060_v2_source_sha_invalid'; end if;
 if nullif(btrim(p_evidence->>'session_id'),'') is null then raise exception 'day060_v2_session_required'; end if;
 if coalesce(p_evidence->>'mode','first_completion') not in ('first_completion','revisit') then raise exception 'day060_v2_mode_invalid'; end if;
 foreach k in array array['public_duration_seconds','partner_duration_seconds'] loop if not coalesce(hnk_private.jsonb_is_nonnegative_integer(p_evidence->k),false) then raise exception 'day060_v2_duration_invalid:%',k; end if; end loop;
 if p_evidence->'voluntary_completion_confirmed' is distinct from 'true'::jsonb or p_evidence->'final_safety_clear_confirmed' is distinct from 'true'::jsonb or p_evidence->'vault_payload_no_identifying_data_confirmed' is distinct from 'true'::jsonb then raise exception 'day060_v2_completion_boundary_required'; end if;
 if jsonb_typeof(p_evidence->'safety_stop_occurred') is distinct from 'boolean' then raise exception 'day060_v2_safety_stop_flag_invalid'; end if;
 if p_evidence->>'safety_stop_reason' not in ('NONE','PRIVACY_CONCERN','CONSENT_WITHDRAWN','FIXATION_CONCERN','DISCOMFORT','OTHER') then raise exception 'day060_v2_safety_reason_invalid'; end if;
 stopped:=(p_evidence->>'safety_stop_occurred')::boolean;if stopped and p_evidence->>'safety_stop_reason'='NONE' then raise exception 'day060_v2_safety_reason_required'; end if;if not stopped and p_evidence->>'safety_stop_reason'<>'NONE' then raise exception 'day060_v2_safety_reason_without_stop'; end if;
 r:=p_evidence->>'vault_entry_ref';if r is null or r!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then raise exception 'day060_v2_vault_ref_invalid'; end if;
 if jsonb_typeof(p_evidence->'public_observations') is distinct from 'array' or jsonb_array_length(p_evidence->'public_observations')<>5 then raise exception 'day060_v2_exactly_five_public_observations_required'; end if;
 for i in 0..4 loop o:=p_evidence->'public_observations'->i;if jsonb_typeof(o) is distinct from 'object' then raise exception 'day060_v2_observation_object_required:%',i+1; end if;if exists(select 1 from jsonb_object_keys(o) x where x not in ('index','feature','distance_bucket','lighting','interpretation_discarded')) then raise exception 'day060_v2_observation_unknown_field:%',i+1; end if;if not coalesce(hnk_private.jsonb_is_nonnegative_integer(o->'index'),false) or (o->>'index')::integer<>i+1 then raise exception 'day060_v2_observation_index_invalid:%',i+1; end if;if o->>'feature' not in ('POSTURE','APPARENT_BREATHING','GAZE_DIRECTION','PUPIL_VISIBILITY','OTHER_VISIBLE_CHANGE') then raise exception 'day060_v2_feature_invalid:%',i+1; end if;if o->>'distance_bucket' not in ('LT_2M','M2_TO_5M','GT_5M','UNKNOWN') then raise exception 'day060_v2_distance_invalid:%',i+1; end if;if o->>'lighting' not in ('BRIGHT','DIM','MIXED','UNKNOWN') then raise exception 'day060_v2_lighting_invalid:%',i+1; end if;if jsonb_typeof(o->'interpretation_discarded') is distinct from 'boolean' then raise exception 'day060_v2_interpretation_discarded_invalid:%',i+1; end if;end loop;
 b:=p_evidence->'public_boundaries';if jsonb_typeof(b) is distinct from 'object' then raise exception 'day060_v2_public_boundaries_required'; end if;if exists(select 1 from jsonb_object_keys(b) x where x not in ('public_context_safe_confirmed','camera_not_used_confirmed','zoom_not_used_confirmed','recognition_not_used_confirmed','identity_not_stored_confirmed','no_prolonged_fixation_confirmed','descriptions_before_interpretation_confirmed','pupil_lighting_primary_variable_confirmed','no_intent_inference_confirmed','no_lie_inference_confirmed','no_attraction_inference_confirmed','no_trauma_inference_confirmed','no_clinical_inference_confirmed')) then raise exception 'day060_v2_public_boundary_unknown_field'; end if;foreach k in array array['public_context_safe_confirmed','camera_not_used_confirmed','zoom_not_used_confirmed','recognition_not_used_confirmed','identity_not_stored_confirmed','no_prolonged_fixation_confirmed','descriptions_before_interpretation_confirmed','pupil_lighting_primary_variable_confirmed','no_intent_inference_confirmed','no_lie_inference_confirmed','no_attraction_inference_confirmed','no_trauma_inference_confirmed','no_clinical_inference_confirmed'] loop if b->k is distinct from 'true'::jsonb then raise exception 'day060_v2_public_boundary_required:%',k; end if; end loop;
 p:=p_evidence->'partner_control';if jsonb_typeof(p) is distinct from 'object' then raise exception 'day060_v2_partner_control_required'; end if;if exists(select 1 from jsonb_object_keys(p) x where x not in ('consent_confirmed','neutral_topics_count','identity_not_stored_confirmed','camera_not_used_confirmed','descriptions_before_feedback_confirmed','only_voluntary_disclosure_compared_confirmed','divergence_not_lie_confirmed','vulnerable_people_not_targeted_confirmed','intimate_situation_not_used_confirmed','comparison_completed_confirmed','exercise_explicitly_ended_confirmed')) then raise exception 'day060_v2_partner_unknown_field'; end if;foreach k in array array['consent_confirmed','identity_not_stored_confirmed','camera_not_used_confirmed','descriptions_before_feedback_confirmed','only_voluntary_disclosure_compared_confirmed','divergence_not_lie_confirmed','vulnerable_people_not_targeted_confirmed','intimate_situation_not_used_confirmed','comparison_completed_confirmed','exercise_explicitly_ended_confirmed'] loop if p->k is distinct from 'true'::jsonb then raise exception 'day060_v2_partner_boundary_required:%',k; end if; end loop;if not coalesce(hnk_private.jsonb_is_nonnegative_integer(p->'neutral_topics_count'),false) or (p->>'neutral_topics_count')::integer<>2 then raise exception 'day060_v2_two_neutral_topics_required'; end if;
 c:=p_evidence->'comparison';if jsonb_typeof(c) is distinct from 'object' then raise exception 'day060_v2_comparison_required'; end if;if exists(select 1 from jsonb_object_keys(c) x where x not in ('correct_inference_count','incorrect_inference_count','unverifiable_inference_count','public_partner_compared_confirmed','errors_preserved_confirmed','competing_variables_preserved_confirmed','mind_reading_not_claimed_confirmed','diagnosis_not_claimed_confirmed','high_impact_not_used_confirmed')) then raise exception 'day060_v2_comparison_unknown_field'; end if;foreach k in array array['correct_inference_count','incorrect_inference_count','unverifiable_inference_count'] loop if not coalesce(hnk_private.jsonb_is_nonnegative_integer(c->k),false) then raise exception 'day060_v2_inference_count_invalid:%',k; end if; end loop;foreach k in array array['public_partner_compared_confirmed','errors_preserved_confirmed','competing_variables_preserved_confirmed','mind_reading_not_claimed_confirmed','diagnosis_not_claimed_confirmed','high_impact_not_used_confirmed'] loop if c->k is distinct from 'true'::jsonb then raise exception 'day060_v2_comparison_boundary_required:%',k; end if; end loop;
 m:=p_evidence->'middle';if jsonb_typeof(m) is distinct from 'object' then raise exception 'day060_v2_middle_required'; end if;if exists(select 1 from jsonb_object_keys(m) x where x not in ('psalm_10_1_confirmed','he_he_aleph_confirmed','observations_reviewed_count','environmental_variables_named_count','unsupported_interpretations_removed_confirmed','partner_thanked_confirmed','vision_rested_confirmed','no_continued_monitoring_confirmed','no_identifiable_data_in_practice_record_confirmed','conscious_return_confirmed')) then raise exception 'day060_v2_middle_unknown_field'; end if;foreach k in array array['psalm_10_1_confirmed','he_he_aleph_confirmed','unsupported_interpretations_removed_confirmed','partner_thanked_confirmed','vision_rested_confirmed','no_continued_monitoring_confirmed','no_identifiable_data_in_practice_record_confirmed','conscious_return_confirmed'] loop if m->k is distinct from 'true'::jsonb then raise exception 'day060_v2_middle_boundary_required:%',k; end if; end loop;if not coalesce(hnk_private.jsonb_is_nonnegative_integer(m->'observations_reviewed_count'),false) or (m->>'observations_reviewed_count')::integer<>3 then raise exception 'day060_v2_three_observations_reviewed_required'; end if;if not coalesce(hnk_private.jsonb_is_nonnegative_integer(m->'environmental_variables_named_count'),false) or (m->>'environmental_variables_named_count')::integer<>3 then raise exception 'day060_v2_three_environmental_variables_required'; end if;
 legacy:=jsonb_build_object('protocol_completed',true,'return_confirmed',m->'conscious_return_confirmed','five_public_observations_completed',true,'camera_not_used',b->'camera_not_used_confirmed','identity_not_stored',b->'identity_not_stored_confirmed','partner_consent',p->'consent_confirmed','partner_comparison_completed',p->'comparison_completed_confirmed','diagnosis_not_claimed',c->'diagnosis_not_claimed_confirmed','mind_reading_not_claimed',c->'mind_reading_not_claimed_confirmed','vulnerable_people_not_targeted',p->'vulnerable_people_not_targeted_confirmed','vault_saved',true,'safety_clear',p_evidence->'final_safety_clear_confirmed','public_observations_count',jsonb_array_length(p_evidence->'public_observations'));perform hnk_private.validate_day060_scalar_evidence_v1(legacy);
end$$;
create or replace function hnk_private.enforce_hahaiah_057_061_scalar_evidence() returns trigger language plpgsql security definer set search_path='' as $$declare v_existing boolean;v_source_sha text;v_status text;begin if new.day not in (57,58,59,60,61) or new.state not in ('evidence_pending','complete') then return new;end if;select exists(select 1 from public.day_completions where user_id=new.user_id and day=new.day) into v_existing;if v_existing then return new;end if;select source_sha,status into v_source_sha,v_status from public.codex_days where day=new.day;if v_status is distinct from 'canon' then raise exception 'hahaiah_canonical_day_not_available';end if;if new.day=57 then if v_source_sha is distinct from 'deb6305d38b89a4168ad5cff083d2b96e7a7fec4' then raise exception 'day057_canonical_source_sha_mismatch';end if;if new.evidence->>'protocol_version'='HNK-CHOKMAH-D057-V2' then perform hnk_private.validate_day057_completion_v2(new.evidence,v_source_sha);else perform hnk_private.validate_day057_scalar_evidence_v1(new.evidence);end if;elsif new.day=58 then if v_source_sha is distinct from 'e32753a57daab23d378e881451194b0dd77d8aac' then raise exception 'day058_canonical_source_sha_mismatch';end if;if new.evidence->>'protocol_version'='HNK-CHOKMAH-D058-V2' then perform hnk_private.validate_day058_completion_v2(new.evidence,v_source_sha);else perform hnk_private.validate_day058_scalar_evidence_v1(new.evidence);end if;elsif new.day=59 then if v_source_sha is distinct from 'e0b9b51cac81012e4511e6394c6f3dff7f50aaf8' then raise exception 'day059_canonical_source_sha_mismatch';end if;if new.evidence->>'protocol_version'='HNK-CHOKMAH-D059-V2' then perform hnk_private.validate_day059_completion_v2(new.evidence,v_source_sha);else perform hnk_private.validate_day059_scalar_evidence_v1(new.evidence);end if;elsif new.day=60 then if v_source_sha is distinct from 'e98e8925c8e03555c39b033813999d6a488149a9' then raise exception 'day060_canonical_source_sha_mismatch';end if;if new.evidence->>'protocol_version'='HNK-CHOKMAH-D060-V2' then perform hnk_private.validate_day060_completion_v2(new.evidence,v_source_sha);else perform hnk_private.validate_day060_scalar_evidence_v1(new.evidence);end if;else if v_source_sha is distinct from '12e4c2da623f2f78d3fea3ff65e23f9446f9784b' then raise exception 'day061_canonical_source_sha_mismatch';end if;perform hnk_private.validate_day061_scalar_evidence_v1(new.evidence);end if;return new;end$$;
do $$ declare v_def text;v_old text;v_new text;begin select pg_get_functiondef('hnk_private.validate_completion_contract_v2(text,jsonb,text)'::regprocedure) into v_def;if position('when ''day060_v2''' in v_def)=0 then v_old:='  else raise exception ''unsupported_completion_validator:%'',p_validator_key;';if position(v_old in v_def)=0 then raise exception 'day060_dispatcher_patch_anchor_missing';end if;v_new:='  when ''day060_v2'' then perform hnk_private.validate_day060_completion_v2(p_evidence,p_expected_source_sha);'||E'\n'||v_old;v_def:=replace(v_def,v_old,v_new);execute v_def;end if;end$$;
insert into hnk_private.completion_contract_registry(completion_contract_id,quest_definition_id,day,canonical_source_sha,contract_version,validator_key,status) values('HNK-CHOKMAH-D060-COMP-V2','HNK-CHOKMAH-D060-V2',60,'e98e8925c8e03555c39b033813999d6a488149a9','2.0.0','day060_v2','draft') on conflict(completion_contract_id) do update set quest_definition_id=excluded.quest_definition_id,day=excluded.day,canonical_source_sha=excluded.canonical_source_sha,contract_version=excluded.contract_version,validator_key=excluded.validator_key,status='draft',updated_at=now();
